insert into public.products (id, category_id, name, slug, description, details, specifications, price, compare_at_price, brand, sku, stock_quantity, sales_count, is_featured, created_at, updated_at) values ('3e75ca87-ed7c-4836-bd46-f055c21e927d', '6ad6e767-dbfd-48cb-9e58-ada0b7adf08c', 'Aurel Studio Wireless Headphones', 'aurel-studio-wireless-headphones', 'Studio-grade sound without the studio. Adaptive noise cancelling reads your surroundings 200 times a second, while 40mm beryllium-coated drivers deliver detail you can feel. Memory-foam cushions wrapped in protein leather keep long listening sessions comfortable.', array['Adaptive active noise cancelling with transparency mode', 'Up to 38 hours of playback, 10 minutes = 5 hours', 'Multipoint Bluetooth 5.3 with LDAC', 'Folds flat into a recycled felt case']::text[], '{"Drivers":"40mm beryllium-coated","Battery life":"38 hours (ANC on)","Charging":"USB-C, fast charge","Weight":"254 g","Connectivity":"Bluetooth 5.3, 3.5mm"}'::jsonb, 725000.00, 907000.00, 'Aurel', 'HF-ELE-1001', 60, 1840, true, now() - interval '40 days 0 hours', now() - interval '40 days 0 hours');
