insert into public.product_questions (product_id, author_name, question, answer, answered_at, created_at) values ('3e75ca87-ed7c-4836-bd46-f055c21e927d', 'Neema M.', 'How long does delivery to Tanzania take?', 'Air cargo takes 10–14 days, express air 5–7 days and sea freight 30–45 days. We deliver to your door in Dar es Salaam, Arusha, Mwanza, Dodoma and other major towns.', now() - interval '3 days 0 hours', now() - interval '20 days 0 hours');
