insert into public.products (id, category_id, name, slug, description, details, specifications, price, compare_at_price, brand, sku, stock_quantity, sales_count, is_featured, created_at, updated_at) values ('e30d0e88-b4d4-4faa-b501-93292d6b5a34', '6ad6e767-dbfd-48cb-9e58-ada0b7adf08c', 'Kova Pods Pro Earbuds', 'kova-pods-pro-earbuds', 'Big sound, tiny footprint. Kova Pods Pro pair dual drivers with hybrid noise cancelling and a pocket-sized wireless charging case, so the music never has to stop.', array['Hybrid ANC with three microphones per bud', 'IPX5 sweat and water resistance', 'Wireless charging case', 'Spatial audio with head tracking']::text[], '{"Battery life":"8 h (buds) + 28 h (case)","Water resistance":"IPX5","Charging":"USB-C, Qi wireless","Weight":"5.1 g per bud"}'::jsonb, 491000.00, 595000.00, 'Kova', 'HF-ELE-1003', 80, 2410, true, now() - interval '25 days 0 hours', now() - interval '25 days 0 hours');
