insert into public.products (id, category_id, name, slug, description, details, specifications, price, compare_at_price, brand, sku, stock_quantity, sales_count, is_featured, created_at, updated_at) values ('8211d30c-b763-46bb-b8e2-7866fddd37d1', '6ad6e767-dbfd-48cb-9e58-ada0b7adf08c', 'Nordlys Pulse Smartwatch', 'nordlys-pulse-smartwatch', 'Your health, at a glance. Pulse tracks heart rate, blood oxygen, sleep stages and 120 workout types on a bright always-on AMOLED display, then keeps going for a full week on a single charge.', array['1.9" always-on AMOLED display', 'Dual-band GPS', '7-day battery life', 'Swim-proof to 50 m']::text[], '{"Display":"1.9\" AMOLED, 2000 nits","Sensors":"HR, SpO2, skin temperature","Water resistance":"5 ATM","Battery":"Up to 7 days"}'::jsonb, 855000.00, null, 'Nordlys', 'HF-ELE-1004', 46, 980, true, now() - interval '12 days 0 hours', now() - interval '12 days 0 hours');
