insert into public.products (id, category_id, name, slug, description, details, specifications, price, compare_at_price, brand, sku, stock_quantity, sales_count, is_featured, created_at, updated_at) values ('e5ad88ec-3e8d-4315-a7f5-b70e3abc123d', '6ad6e767-dbfd-48cb-9e58-ada0b7adf08c', 'Nordlys Arc Ceramic Watch', 'nordlys-arc-ceramic-watch', 'A smartwatch dressed as a classic. A polished white ceramic case and fluoroelastomer strap hide everyday smarts: notifications, contactless payments and quiet haptic alarms.', array['Scratch-resistant ceramic case', 'Contactless payments', '5-day battery', 'Interchangeable 20mm straps']::text[], '{"Case":"40mm ceramic","Water resistance":"3 ATM","Battery":"Up to 5 days"}'::jsonb, 647000.00, 777000.00, 'Nordlys', 'HF-ELE-1005', 18, 410, false, now() - interval '210 days 0 hours', now() - interval '210 days 0 hours');
