insert into public.product_questions (product_id, author_name, question, answer, answered_at, created_at) values ('3ffb2fc8-9457-456b-9d6b-4f71c7107129', 'Hamisi J.', 'How long does delivery to Tanzania take?', 'Air cargo takes 10–14 days, express air 5–7 days and sea freight 30–45 days. We deliver to your door in Dar es Salaam, Arusha, Mwanza, Dodoma and other major towns.', now() - interval '5 days 0 hours', now() - interval '28 days 0 hours');
insert into public.product_questions (product_id, author_name, question, answer, answered_at, created_at) values ('3ffb2fc8-9457-456b-9d6b-4f71c7107129', 'Asha H.', 'Do I have to pay customs when it arrives?', 'No. Import duties and clearing are handled by us. VAT (18%) is shown at checkout, so there are no surprises on delivery.', now() - interval '5 days 0 hours', now() - interval '20 days 0 hours');
insert into public.product_questions (product_id, author_name, question, answer, answered_at, created_at) values ('3ffb2fc8-9457-456b-9d6b-4f71c7107129', 'Faraja M.', 'Can I pay with M-Pesa?', 'Yes. We accept M-Pesa, Tigo Pesa, Airtel Money and HaloPesa, as well as Visa and Mastercard.', now() - interval '3 days 0 hours', now() - interval '18 days 0 hours');
