insert into public.product_questions (product_id, author_name, question, answer, answered_at, created_at) values ('a22e4257-208c-4319-b1d1-efb09618de40', 'Esther N.', 'How long does delivery to Tanzania take?', 'Air cargo takes 10–14 days, express air 5–7 days and sea freight 30–45 days. We deliver to your door in Dar es Salaam, Arusha, Mwanza, Dodoma and other major towns.', now() - interval '5 days 0 hours', now() - interval '13 days 0 hours');
