insert into public.product_questions (product_id, author_name, question, answer, answered_at, created_at) values ('a22e4257-208c-4319-b1d1-efb09618de40', 'Grace W.', 'Can I pay with M-Pesa?', 'Yes. We accept M-Pesa, Tigo Pesa, Airtel Money and HaloPesa, as well as Visa and Mastercard.', now() - interval '5 days 0 hours', now() - interval '11 days 0 hours');
