insert into public.product_questions (product_id, author_name, question, answer, answered_at, created_at) values ('069ed0fe-2cfc-47af-a3b7-01306fbc36d4', 'Upendo R.', 'Can I return it if it doesn''t suit me?', 'Yes. You have 14 days after delivery to return unused items. Drop-off is free at our Dar es Salaam collection point.', now() - interval '1 days 0 hours', now() - interval '19 days 0 hours');
insert into public.product_questions (product_id, author_name, question, answer, answered_at, created_at) values ('069ed0fe-2cfc-47af-a3b7-01306fbc36d4', 'Esther N.', 'Is this original quality?', 'Yes. We buy directly from verified factories in Guangzhou, Shenzhen and Yiwu and inspect every order before it ships to Tanzania.', now() - interval '4 days 0 hours', now() - interval '6 days 0 hours');
insert into public.product_questions (product_id, author_name, question, answer, answered_at, created_at) values ('069ed0fe-2cfc-47af-a3b7-01306fbc36d4', 'Daudi T.', 'How long does delivery to Tanzania take?', 'Air cargo takes 10–14 days, express air 5–7 days and sea freight 30–45 days. We deliver to your door in Dar es Salaam, Arusha, Mwanza, Dodoma and other major towns.', now() - interval '3 days 0 hours', now() - interval '9 days 0 hours');
